test('local video activity is observable only for the current Blob player', () => {
  const current = {
    mediaElementMatches: true,
    sourceUrlMatches: true,
    bindingMatches: true,
  };
  for (const activity of ['playing', 'paused', 'ended'] as const) {
    assert.deepEqual(observeVideoLocalPlaybackActivity(current, activity), {
      activity,
      currentLocalPlayer: true,
      browserPlaybackObserved: true,
      decodedFramesVerified: false,
      canonicalTimelineEvidence: false,
      playbackAuthorityGranted: false,
    });
  }
  for (const field of Object.keys(current) as Array<keyof typeof current>) {
    assert.equal(observeVideoLocalPlaybackActivity({
      ...current,
      [field]: false,
    }, 'playing'), null);
  }
  assert.throws(() => observeVideoLocalPlaybackActivity(
    current,
    'buffering' as 'playing',
  ));
  assert.throws(() => observeVideoLocalPlaybackActivity({
    ...current,
    mediaElementMatches: 'yes' as unknown as boolean,
  }, 'playing'));
});

