use anyhow::{bail, Result};
use unicodex_core::ObjectStore;

use super::{context_bound, input_cid, value, verify_closure};
use crate::program_module::runtime::PinnedCall;

pub(super) struct VerifiedBinding {
    pub(super) invocation_context_cid: Option<String>,
}

pub(in crate::program_module::runtime::foreign_process) fn verify_for_operation(
    store: &ObjectStore,
    authorization_cid: &str,
    slot: &str,
    pinned: &PinnedCall,
    input: &str,
) -> Result<()> {
    verify_bound(
        store,
        authorization_cid,
        slot,
        &pinned.record_cid,
        &pinned.module_cid,
        pinned.epoch,
        input,
    )
}

pub(in crate::program_module::runtime::foreign_process) fn verify_bound(
    store: &ObjectStore,
    authorization_cid: &str,
    slot: &str,
    record_cid: &str,
    module_cid: &str,
    epoch: u64,
    input: &str,
) -> Result<()> {
    let input_cid = input_cid(input)?;
    if let Ok(stored) = value::load(store, authorization_cid) {
        if stored.slot != slot
            || stored.record_cid != record_cid
            || stored.module_cid != module_cid
            || stored.epoch != epoch
            || stored.input_cid != input_cid
        {
            bail!("foreign-process call authorization pinned selector mismatch");
        }
        let closure = verify_closure(store, slot, &stored.record_cid, input)?;
        if closure.module_cid != stored.module_cid
            || closure.epoch != stored.epoch
            || closure.input_cid != stored.input_cid
        {
            bail!("foreign-process call authorization closure mismatch");
        }
        return Ok(VerifiedBinding {
            invocation_context_cid: None,
        });
    }
    let authorized = context_bound::verify(store, authorization_cid)?;
    let context = authorized.context.invocation;
    if context.slot != slot
        || context.record_cid != record_cid
        || context.module_cid != module_cid
        || context.epoch != epoch
        || context.input_cid != input_cid
    {
        bail!("foreign-process context-bound call authorization selector mismatch");
    }
    Ok(VerifiedBinding {
        invocation_context_cid: Some(authorized.context.cid),
    })
}

